(async()=>{
let page;
try{
const fonts={body:{family:'Inter',style:'Regular'},medium:{family:'Inter',style:'Semi Bold'},bold:{family:'Inter',style:'Bold'},heading:{family:'Nunito',style:'ExtraBold'}};
await figma.loadFontAsync(fonts.body);
for(const k of ['medium','bold','heading']){try{await figma.loadFontAsync(fonts[k]);}catch(e){fonts[k]=fonts.body;}}
const color=h=>({r:parseInt(h.slice(1,3),16)/255,g:parseInt(h.slice(3,5),16)/255,b:parseInt(h.slice(5,7),16)/255});
const paint=h=>[{type:'SOLID',color:color(h)}];
page=figma.createPage();page.name='Rafiqi / Wireframes / '+new Date().toISOString().slice(0,16).replace('T',' ');
await figma.setCurrentPageAsync(page);
const frames=new Map(),pending=[];
const rowHeight=Math.max(...SCREENS.map(s=>s.height))+160;
for(let i=0;i<SCREENS.length;i++){
const s=SCREENS[i],frame=figma.createFrame();
page.appendChild(frame);frame.name=s.id+' / '+s.role+' / '+s.title;frame.resize(s.width,s.height);
frame.x=(i%4)*(s.width+120);frame.y=Math.floor(i/4)*rowHeight;frame.fills=paint('#F7F7F5');frame.clipsContent=true;
frame.setPluginData('rafiqiSourceRoute',s.route);frame.setPluginData('rafiqiWireframeId',s.id);frames.set(s.id,frame);
const groups=new Map();
for(const o of s.ops){
if(o.name==='Canvas')continue;
let group=groups.get(o.section);
if(!group){group=figma.createFrame();frame.appendChild(group);group.name=o.section;group.resize(s.width,s.height);group.x=0;group.y=0;group.fills=[];group.clipsContent=false;groups.set(o.section,group);}
let node;
if(o.type==='rect'){
node=figma.createRectangle();node.resize(o.w,o.h);node.cornerRadius=o.r;node.fills=paint(o.fill);
node.strokes=o.stroke==='none'?[]:paint(o.stroke);node.strokeWeight=1;
}else{
node=figma.createText();node.fontName=o.weight>=800?fonts.heading:o.weight>=700?fonts.bold:o.weight>=600?fonts.medium:fonts.body;
node.fontSize=o.size;node.lineHeight={unit:'PIXELS',value:o.size+7};node.characters=o.text;node.fills=paint(o.color);
node.resize(o.w,o.size+9);node.textAutoResize='HEIGHT';
}
group.appendChild(node);node.x=o.x;node.y=o.y;node.name=o.name;
}
for(const l of s.links)pending.push({frame,link:l});
if(i%8===0)figma.notify('Creating Rafiqi wireframes: '+(i+1)+' / '+SCREENS.length,{timeout:1800});
}
for(const p of pending){
const target=frames.get(p.link.target);if(!target)continue;
const n=figma.createFrame();p.frame.appendChild(n);n.name='Navigate / '+p.link.name+' / '+p.link.target;
n.x=p.link.x;n.y=p.link.y;n.resize(p.link.w,p.link.h);n.fills=[{type:'SOLID',color:{r:1,g:1,b:1},opacity:0}];
await n.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:target.id,navigation:'NAVIGATE',transition:null,preserveScrollPosition:false}]}]);
}
page.selection=[frames.get('T01')];figma.viewport.scrollAndZoomIntoView([frames.get('T01')]);
figma.closePlugin('Created '+SCREENS.length+' editable wireframe frames and '+pending.length+' navigation links. Start at T01 or S01.');
}catch(e){figma.closePlugin('Import stopped: '+String(e)+'. A new Rafiqi page may contain partial output; existing pages were not modified.');}
})();
